const el=id=>document.getElementById(id);let recording=null,shots=[],playing=null;
try{const saved=JSON.parse(localStorage.getItem('battleship-strategies')||'null');if(saved){el('promptA').value=saved.A;el('promptB').value=saved.B;}}catch{}
function prompts(){const A=el('promptA').value.trim(),B=el('promptB').value.trim();if(!A||!B)throw Error('Enter a strategy for both seats.');return {A,B};}
el('save').onclick=()=>{try{localStorage.setItem('battleship-strategies',JSON.stringify(prompts()));el('draftStatus').textContent='Both drafts saved in this browser.';}catch(e){el('draftStatus').textContent=e.message;}};
el('export').onclick=()=>{try{const data={version:1,strategies:prompts()},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='match-prompts.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);el('draftStatus').textContent='Exported prompts for the local MCP match runner.';}catch(e){el('draftStatus').textContent=e.message;}};
fetch('base-prompt.txt').then(r=>{if(!r.ok)throw Error();return r.text();}).then(t=>el('base').textContent=t).catch(()=>el('base').textContent='Base prompt is unavailable.');
function render(){const n=Number(el('step').value),history=shots.slice(0,n),last=history.at(-1);el('stepLabel').textContent=n+' / '+shots.length;el('turnText').textContent=last?'Seat '+last.seat+' fired at '+last.coordinate:'Before the first shot';for(const seat of ['A','B']){const board=el('board'+seat);board.replaceChildren();const corner=document.createElement('span');board.append(corner);for(let c=1;c<=10;c++){const x=document.createElement('span');x.className='coord';x.textContent=c;board.append(x);}const fleet=recording.players[seat].fleet.flatMap(s=>s.cells),incoming=history.filter(s=>s.seat!==seat),own=history.filter(s=>s.seat===seat);el('stats'+seat).textContent=own.length+' shots · '+own.filter(s=>s.hit).length+' hits · '+own.filter(s=>s.sunk).length+' ships sunk';for(let r=0;r<10;r++){const label=document.createElement('span');label.className='coord';label.textContent=String.fromCharCode(65+r);board.append(label);for(let c=1;c<=10;c++){const coordinate=String.fromCharCode(65+r)+c,shot=incoming.find(s=>s.coordinate===coordinate),cell=document.createElement('div');cell.className='cell'+(fleet.includes(coordinate)?' ship':'')+(shot?(shot.hit?' hit':' miss'):'')+(last&&last.seat!==seat&&last.coordinate===coordinate?' last':'');if(shot?.hit)cell.textContent='×';cell.title=coordinate+(shot?(shot.hit?' · hit':' · miss'):fleet.includes(coordinate)?' · ship':'');board.append(cell);}}}el('reason').textContent=last?'Seat '+last.seat+' → '+last.coordinate+' · '+(last.sunk?last.size+' ship sunk':last.hit?'hit':'miss')+' — '+last.reason:'Choose a shot to see its result and tactical note.';}
function stop(){clearInterval(playing);playing=null;el('play').textContent='▶ Play replay';}
el('step').oninput=()=>{stop();render();};el('play').onclick=()=>{if(playing){stop();return;}if(Number(el('step').value)===shots.length)el('step').value=0;el('play').textContent='Ⅱ Pause';playing=setInterval(()=>{el('step').value=Number(el('step').value)+1;render();if(Number(el('step').value)>=shots.length)stop();},850);};
fetch('match-replay.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{recording=data;shots=data.events.filter(e=>e.type==='shot');el('result').textContent='Seat '+data.winner+' wins · '+data.players[data.winner].name;el('matchSummary').textContent=shots.length+' total shots. Two Terra agents, low reasoning effort, separate strategy prompts.';el('usedPrompts').textContent='A — '+data.players.A.strategy+'\n\nB — '+data.players.B.strategy;el('step').max=shots.length;el('step').disabled=false;el('play').disabled=false;render();}).catch(()=>{el('matchSummary').textContent='The exhibition recording will appear here after the match finishes.';el('downloadReplay').hidden=true;});
